    matrices = np.asarray(matrices)
    if matrices.ndim < 2 or matrices.shape[-1] != matrices.shape[-2]:
        return np.bool_(False)
    batch = matrices.reshape(-1, matrices.shape[-2], matrices.shape[-1])
    for m in batch:
        try:
