from sympy import *

def custom_check_carmichael(n: int) -> bool:
    n = int(n)
    if n < 2 or isprime(n):
        return False
    factors = factorint(n)
    # Korselt's criterion requires n to be squarefree
    if any(e > 1 for e in factors.values()):
        return False
    # A composite squarefree number needs at least two distinct primes
    if len(factors) < 2:
        return False
    # For every prime p dividing n, (p - 1) must divide (n - 1)
    return all((n - 1) % (p - 1) == 0 for p in factors)

